"use client";

import { useEffect, useState } from "react";
import { COURSES, SITE, rupees, whatsappUrl } from "@/lib/site";
import { SELECT_COURSE_EVENT } from "./CourseCards";

type Note = { text: string; kind: "error" | "success" } | null;

// No backend yet: on submit, the details are sent as a pre-filled WhatsApp message.
// To use an API route / payment gateway instead, replace the body of submitEnrollment().
function submitEnrollment(data: Record<string, string>) {
  const course = COURSES.find((c) => c.id === data.course);
  const msg =
    `Hi! I want to book my seat (${rupees(SITE.price)}).\n\n` +
    `Name: ${data.name}\nMobile: ${data.phone}\nEmail: ${data.email}\n` +
    `City: ${data.city}\nCourse: ${course ? course.name : data.course}\nStatus: ${data.status}`;
  window.open(whatsappUrl(msg), "_blank", "noopener");
}

export default function EnrollForm() {
  const [course, setCourse] = useState("");
  const [invalid, setInvalid] = useState<Set<string>>(new Set());
  const [note, setNote] = useState<Note>(null);

  // "Enroll Now" on a course card pre-selects that course here.
  useEffect(() => {
    const onSelect = (e: Event) => setCourse((e as CustomEvent<string>).detail);
    window.addEventListener(SELECT_COURSE_EVENT, onSelect);
    return () => window.removeEventListener(SELECT_COURSE_EVENT, onSelect);
  }, []);

  function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    const fields = Array.from(form.querySelectorAll<HTMLInputElement | HTMLSelectElement>("input, select"));
    const bad = fields.filter((el) => !el.checkValidity());
    setInvalid(new Set(bad.map((el) => el.name)));
    if (bad.length) {
      setNote({ text: "Please fill in all fields correctly.", kind: "error" });
      bad[0].focus();
      return;
    }
    submitEnrollment(Object.fromEntries(new FormData(form)) as Record<string, string>);
    setNote({
      text: "Thanks! Your details are ready to send on WhatsApp. Our team will confirm your seat shortly.",
      kind: "success",
    });
    form.reset();
    setCourse("");
  }

  function clearIfValid(e: React.FormEvent<HTMLFormElement>) {
    const el = e.target as HTMLInputElement;
    if (invalid.has(el.name) && el.checkValidity()) {
      const next = new Set(invalid);
      next.delete(el.name);
      setInvalid(next);
    }
  }

  const fieldClass = (name: string) => `field${invalid.has(name) ? " invalid" : ""}`;

  return (
    <form className="enroll-form" noValidate onSubmit={handleSubmit} onInput={clearIfValid}>
      <h3>Book My Seat for ₹{SITE.price}</h3>
      <p className="form-sub">Takes 30 seconds. Our team will confirm your batch on WhatsApp.</p>
      <div className={fieldClass("name")}>
        <label htmlFor="f-name">Full Name</label>
        <input id="f-name" name="name" type="text" autoComplete="name" required placeholder="Your full name" />
      </div>
      <div className={fieldClass("phone")}>
        <label htmlFor="f-phone">Mobile Number (WhatsApp)</label>
        <input
          id="f-phone"
          name="phone"
          type="tel"
          autoComplete="tel"
          inputMode="numeric"
          required
          pattern="[6-9][0-9]{9}"
          maxLength={10}
          placeholder="10-digit mobile number"
        />
      </div>
      <div className={fieldClass("email")}>
        <label htmlFor="f-email">Email</label>
        <input id="f-email" name="email" type="email" autoComplete="email" required placeholder="you@example.com" />
      </div>
      <div className={fieldClass("city")}>
        <label htmlFor="f-city">City</label>
        <input id="f-city" name="city" type="text" autoComplete="address-level2" required placeholder="Your city" />
      </div>
      <div className="field-row">
        <div className={fieldClass("course")}>
          <label htmlFor="f-course">Select Course</label>
          <select id="f-course" name="course" required value={course} onChange={(e) => setCourse(e.target.value)}>
            <option value="" disabled>
              Choose a course
            </option>
            {COURSES.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        </div>
        <div className={fieldClass("status")}>
          <label htmlFor="f-status">Current Status</label>
          <select id="f-status" name="status" required defaultValue="">
            <option value="" disabled>
              Select
            </option>
            <option>Student</option>
            <option>Working Professional</option>
            <option>Business Owner</option>
            <option>Other</option>
          </select>
        </div>
      </div>
      <button type="submit" className="btn btn-primary btn-lg btn-block">
        Confirm My Seat <span className="arrow">→</span>
      </button>
      <p className="secure">🔒 Your details are only used to contact you about your enrollment.</p>
      <p className={`form-note${note ? " " + note.kind : ""}`} role="status" aria-live="polite">
        {note?.text}
      </p>
    </form>
  );
}
