"use client";

import { useRef, useState } from "react";
import { COURSES, SITE, rupees, type Course } from "@/lib/site";

export const SELECT_COURSE_EVENT = "select-course";

export default function CourseCards() {
  return (
    <div className="cards" data-stagger>
      {COURSES.map((c, i) => (
        <CourseCard key={c.id} course={c} index={i} />
      ))}
    </div>
  );
}

function CourseCard({ course: c, index }: { course: Course; index: number }) {
  const [flipped, setFlipped] = useState(false);
  const frontBtn = useRef<HTMLButtonElement>(null);
  const enrollBtn = useRef<HTMLAnchorElement>(null);

  const meta = [c.level, c.hours ? `${c.hours} Hours` : null, "Live Classes"].filter(Boolean);
  const price = (
    <span className="price">
      {c.originalPrice ? <s>{rupees(c.originalPrice)}</s> : null}
      {rupees(SITE.price)}
    </span>
  );

  function toggle() {
    const next = !flipped;
    setFlipped(next);
    // Move focus to the face that's now visible.
    requestAnimationFrame(() => (next ? enrollBtn : frontBtn).current?.focus({ preventScroll: true }));
  }

  return (
    <article
      className={`card${flipped ? " flipped" : ""}`}
      style={{ "--accent": c.accent } as React.CSSProperties}
      data-tilt
      onClick={toggle}
    >
      <div className="card-inner">
        <div className="card-face card-front" aria-hidden={flipped}>
          <span className="card-num" aria-hidden="true">
            {String(index + 1).padStart(2, "0")}
          </span>
          <span className="card-emoji" aria-hidden="true">
            {c.emoji}
          </span>
          <h3>{c.name}</h3>
          <p className="tagline">{c.tagline}</p>
          <ul className="meta">
            {meta.map((m) => (
              <li key={m}>{m}</li>
            ))}
          </ul>
          <div className="card-foot">
            {price}
            <button ref={frontBtn} type="button" className="flip-btn" aria-expanded={flipped} tabIndex={flipped ? -1 : 0}>
              See what&apos;s inside <span className="ic">↻</span>
            </button>
          </div>
        </div>

        <div className="card-face card-back" aria-hidden={!flipped}>
          <h4>What you&apos;ll learn</h4>
          <ul className="learn">
            {c.learn.map((l) => (
              <li key={l}>{l}</li>
            ))}
          </ul>
          <dl>
            <dt>Tools</dt>
            <dd>{c.tools.join(", ")}</dd>
            <dt>Who it&apos;s for</dt>
            <dd>{c.audience}</dd>
            <dt>Career paths</dt>
            <dd>{c.careers.join(", ")}</dd>
          </dl>
          <div className="card-foot">
            {price}
            <button type="button" className="flip-btn back-btn" tabIndex={flipped ? 0 : -1} aria-label="Flip card back">
              ↺
            </button>
          </div>
          <a
            ref={enrollBtn}
            href="#enroll"
            className="btn btn-primary btn-block enroll-btn"
            tabIndex={flipped ? 0 : -1}
            onClick={(e) => {
              e.stopPropagation();
              window.dispatchEvent(new CustomEvent(SELECT_COURSE_EVENT, { detail: c.id }));
            }}
          >
            Enroll Now – {c.short ?? c.name}
          </a>
        </div>
      </div>
    </article>
  );
}
